package controle;
import conexao.Conexao;import dao.MatriculaDAO;import java.awt.*;import java.time.LocalDate;import javax.swing.*;import javax.swing.table.DefaultTableModel;import modelo.Matricula;
public class TelaMatricula extends JFrame{private final Conexao con=new Conexao();private MatriculaDAO dao;private final JTextField id=new JTextField(),data=new JTextField(LocalDate.now().toString()),aluno=new JTextField(),turma=new JTextField();private final JComboBox<String> situacao=new JComboBox<>(new String[]{"ATIVA","CANCELADA","TRANCADA"});private final DefaultTableModel m=new DefaultTableModel(new String[]{"Código","Data","Situação","Aluno","Turma"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);public TelaMatricula(){setTitle("Matrículas");setSize(760,450);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new GridLayout(5,2,5,5));id.setEditable(false);p.add(new JLabel("Código:"));p.add(id);p.add(new JLabel("Data (AAAA-MM-DD):"));p.add(data);p.add(new JLabel("Situação:"));p.add(situacao);p.add(new JLabel("Código aluno:"));p.add(aluno);p.add(new JLabel("Código turma:"));p.add(turma);JPanel b=new JPanel();for(String s:new String[]{"Nova","Salvar","Excluir","Fechar"}){JButton x=new JButton(s);b.add(x);if(s.equals("Nova"))x.addActionListener(e->limpar());if(s.equals("Salvar"))x.addActionListener(e->salvar());if(s.equals("Excluir"))x.addActionListener(e->excluir());if(s.equals("Fechar"))x.addActionListener(e->dispose());}JPanel n=new JPanel(new BorderLayout());n.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));n.add(p);n.add(b,BorderLayout.SOUTH);add(n,BorderLayout.NORTH);add(new JScrollPane(t));t.getSelectionModel().addListSelectionListener(e->{int r=t.getSelectedRow();if(r>=0&&!e.getValueIsAdjusting()){id.setText(m.getValueAt(r,0).toString());data.setText(m.getValueAt(r,1).toString());situacao.setSelectedItem(m.getValueAt(r,2).toString());aluno.setText(m.getValueAt(r,3).toString());turma.setText(m.getValueAt(r,4).toString());}});if(con.conecta()){dao=new MatriculaDAO(con);carregar();}addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){con.desconecta();}});}private void carregar(){if(dao==null)return;try{m.setRowCount(0);for(Matricula x:dao.listar())m.addRow(new Object[]{x.getIdMatricula(),x.getDataMatricula(),x.getSituacao(),x.getIdAluno(),x.getIdTurma()});}catch(Exception e){erro(e);}}private void limpar(){id.setText("");data.setText(LocalDate.now().toString());aluno.setText("");turma.setText("");situacao.setSelectedIndex(0);}private void salvar(){try{if(id.getText().isBlank()){Matricula x=new Matricula();x.setDataMatricula(LocalDate.parse(data.getText()));x.setSituacao(situacao.getSelectedItem().toString());x.setIdAluno(Integer.parseInt(aluno.getText()));x.setIdTurma(Integer.parseInt(turma.getText()));dao.inserir(x);}else dao.atualizarSituacao(Integer.parseInt(id.getText()),situacao.getSelectedItem().toString());carregar();limpar();}catch(Exception e){erro(e);}}private void excluir(){if(id.getText().isBlank())return;try{dao.excluir(Integer.parseInt(id.getText()));carregar();limpar();}catch(Exception e){erro(e);}}private void erro(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Erro",JOptionPane.ERROR_MESSAGE);}}
